// La autenticación la hace el propio webhook con una credencial de cabecera:
// n8n Cloud no deja leer variables de entorno desde aquí, y comprobarlo en el
// nodo de entrada es mejor de todos modos porque rechaza antes de ejecutar.
const d = $input.first().json.body || $input.first().json;

const esc = (s) => String(s == null ? '' : s)
  .replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

// Un reenvío es un aviso de un lead que ya entró: sirve para poner al día a
// alguien que se acaba de añadir a la lista. Nunca vuelve a mandarle la guía
// al lead, que ya la recibió el primer día.
const reenvio = d.reenvio === true;

const caliente = d.tier === 'HOT';
// wa.me solo entiende el formato internacional. Se escribe «636142591» o
// «0034 628…» y los dos dan un enlace muerto: el botón no abría nada.
const tel = (() => {
  let x = String(d.telefono || '').replace(/\D/g, '');
  if (!x) return '';
  if (x.startsWith('00')) x = x.slice(2);
  if (x.length === 9 && /^[6789]/.test(x)) x = '34' + x;
  return (x.length >= 8 && x.length <= 15) ? x : '';
})();
const ORIGEN = { guia: 'Descargó la guía', cuestionario: 'Rellenó el cuestionario', meta_form: 'Formulario de Meta' };

// ── Aviso al comercial ─────────────────────────────────────────────────────
// El asunto lleva delante lo que decide si hay que abrirlo ahora o luego: es
// lo único que se lee desde la pantalla de bloqueo del móvil.
const asunto = (reenvio ? 'Copia \u00b7 ' : '')
  + (caliente ? '\u{1F525} LEAD HOT · ' : 'Lead nuevo · ')
  + (d.nombre || 'sin nombre')
  + (d.pieza ? ' · ' + d.pieza : '')
  + (d.medidas ? ' ' + d.medidas : '');

const filas = [
  ['Teléfono', d.telefono], ['Email', d.email],
  ['Pieza', d.pieza], ['Dónde va', d.espacio], ['Medidas', d.medidas],
  ['Estilo', d.estilo], ['Presupuesto', d.presupuesto], ['Plazo', d.plazo],
  ['Referencias', d.referencias],
  ['Origen', ORIGEN[d.origen] || d.origen],
  ['Campaña', d.utm_campaign], ['Anuncio', d.utm_content],
].filter(([, v]) => v).map(([k, v]) =>
  `<tr><td style="padding:5px 16px 5px 0;color:#7C7266;vertical-align:top;white-space:nowrap">${esc(k)}</td>`
  + `<td style="padding:5px 0;color:#332B23"><b>${esc(v)}</b></td></tr>`).join('');

const html = `<div style="font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:15px;line-height:1.55;color:#332B23;max-width:560px">
${caliente ? `<p style="background:#FCE8E6;border-left:3px solid #B3261E;padding:11px 14px;margin:0 0 18px;border-radius:0 6px 6px 0">
<b>Lead HOT.</b> Proyecto definido, presupuesto y plazo cercano.<br>WhatsApp en menos de 2 horas laborables.</p>` : ''}
<h2 style="margin:0 0 2px;font-size:20px;color:#14100D">${esc(d.nombre || 'Sin nombre')}</h2>
<p style="margin:0 0 18px;color:#7C7266;font-size:13px">${esc(ORIGEN[d.origen] || d.origen || '')}${d.fecha_original ? ' \u00b7 entr\u00f3 el ' + esc(d.fecha_original) : ''}</p>
${reenvio ? '<p style="background:#F4EFE7;padding:9px 13px;margin:0 0 18px;border-radius:6px;font-size:13px;color:#5B5046">Copia de un lead anterior. Ya est\u00e1 en el CRM y ya recibi\u00f3 lo que le tocaba.</p>' : ''}
<table style="border-collapse:collapse;font-size:14px">${filas}</table>
<p style="margin:24px 0 0">
${tel ? `<a href="https://wa.me/${tel}" style="background:#8C5E32;color:#fff;padding:11px 20px;border-radius:999px;text-decoration:none;display:inline-block;font-weight:600">Escribir por WhatsApp</a>&nbsp;&nbsp;` : ''}
<a href="https://antic-barcelona-113.vercel.app/crm" style="color:#8C5E32;text-decoration:none">Abrir el CRM →</a></p>
<p style="margin-top:26px;color:#A79C8E;font-size:12px">Antic Barcelona 113 · aviso automático</p></div>`;

// ── Correo al lead con la guía ───────────────────────────────────────────
// Lo prometemos en el anuncio: si no llega, hemos pagado por un clic y hemos
// quedado mal. Va aquí y no en Apps Script para no depender de un despliegue.
const nombre = String(d.nombre || '').trim().split(' ')[0];
const htmlGuia = `<div style="font-family:Georgia,'Times New Roman',serif;font-size:16px;line-height:1.65;color:#332B23;max-width:560px">
<p>Hola${nombre ? ' ' + esc(nombre) : ''},</p>
<p>Aquí tienes la guía. Son siete apartados con lo que preguntamos a todos
nuestros clientes antes de empezar: medidas, comensales, maderas, acabados,
qué encarece una pieza de verdad y los plazos reales.</p>
<p>Si te quedas con una sola cosa, que sea la tabla de medidas del apartado
dos. Es la que evita el error más caro: encargar una mesa que no deja pasar
por detrás de las sillas.</p>
<p>Y si ya tienes un espacio concreto en la cabeza, cuéntanoslo y te decimos
qué encaja:<br>
<a href="https://antic-barcelona-113.vercel.app/cuestionario" style="color:#8C5E32">Diseña tu pieza →</a></p>
<p style="color:#7C7266;font-size:14px;margin-top:26px">Un saludo,<br>
El equipo de Antic Barcelona 113<br>
Taller en Terrassa · +34 665 521 684</p></div>`;

return [{ json: {
  asunto, html,
  esGuia: d.origen === 'guia' && !!d.email && !reenvio,
  emailLead: d.email || '',
  asuntoGuia: 'Tu guía para elegir la mesa perfecta',
  htmlGuia,
} }];
